async (page) => {
  await page.evaluate(() => {
    window.forumName = 'women_shots';
    window.forumTitle = 'women_shots';
    window.forumDesc = 'Best candid shots of women in the wild';
    window.forumSidebar = 'Back angle shots, Front angle shots';
  });

  // Verify the variables were set
  const result = await page.evaluate(() => ({
    forumName: window.forumName,
    forumTitle: window.forumTitle,
    forumDesc: window.forumDesc,
    forumSidebar: window.forumSidebar
  }));

  return result;
}

async (page) => {
  const name = await page.evaluate(() => window.forumName);
  const title = await page.evaluate(() => window.forumTitle);
  const desc = await page.evaluate(() => window.forumDesc);
  const sidebar = await page.evaluate(() => window.forumSidebar);

  await page.fill('#forum_name', name);
  await page.fill('#forum_title', title);
  await page.fill('#forum_description', desc);
  await page.fill('#forum_sidebar', sidebar);
  await page.click('button.button');

  return {
    forumName: name,
    forumTitle: title,
    forumDescription: desc,
    forumSidebar: sidebar,
    status: 'Form submitted successfully'
  };
}
